window.kbPageData["views/entry/k-b2837c1766d1a5a7"] = {"key":"entry/k-b2837c1766d1a5a7","state":{"route":"entry/k-b2837c1766d1a5a7"},"node":{"id":"k-b2837c1766d1a5a7","mode":"k","title":"实践与认识","type":"原理与机制","domain":"哲学","reading":"","intro":"","priority":100,"aliases":["认识论 · 实践和认识的辩证关系"],"qs":["政治理论必刷100题#2","政治理论必刷100题#7"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"reviewDoubt":"政治理论必刷100题 · 第 2 题《政治理论必刷100题》第2题给定答案为C。A项引文足以说明生态保护对生产力的作用，原解析却未说明题中哪两个方面构成所说的矛盾双方、哪一方在何种条件下转为其对立面。A项能否判为正确、C能否作为唯一错误项，现有原文仍无法确认。","tags":{"主类":["原理与机制"],"出处性质":["专项题干","专项题解析","理论手册"],"学科":["哲学"],"来源主题":["马克思主义哲学"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"在马克思主义认识论中，实践是认识的来源和发展的动力，也是检验认识真理性的唯一标准。认识反过来指导实践，正确认识能够促进实践。","review":{"title":"实践与认识","type":"原理与机制","definition":"在马克思主义认识论中，实践是认识的来源和发展的动力，也是检验认识真理性的唯一标准。认识反过来指导实践，正确认识能够促进实践。","explanation":"认识与实践的具体的历史的统一，要求认识同一定时间、地点和条件下的实践相符合，并随实践的发展而发展。理论指导能否取得预期成果，还取决于实践条件和实施过程。","basis":"据关联原题及所列出处编释。","references":[{"source":"web-2e6ec1ddf52d7118","location":"2013年5月24日十八届中央政治局第六次集体学习讲话节录","quote":"生态兴则文明兴，生态衰则文明衰"},{"source":"web-90788cbf4d8cf58e","location":"1859年序言，阐述社会生产、经济结构与社会意识的段落","quote":"物质生活的生产方式制约着整个社会生活、政治生活和精神生活的过程。"},{"source":"web-c3283fe1a8c34858","location":"第五节，矛盾诸方面的同一性和斗争性","quote":"依据一定的条件，各向着其相反的方面转化"}],"examFocus":{"政治理论必刷100题#2":"逐组核对生态文明论述所说明的哲学关系，辨别论述有没有交代相应原理所需的条件。","政治理论必刷100题#7":"结合全国统一大市场建设，辨明部署、落实过程和实际成效在各项论述中的作用。"}},"aspects":[{"title":"认识与实践的具体的历史的统一","uses":[{"unit":"Q1","role":"解题依据","use":"《政治理论必刷100题》第2题要求选出对应错误的一项，所给答案为C。“生态兴则文明兴”强调生态状况对文明兴衰的影响，单凭这句话无法说明认识如何同特定历史条件下的实践相符合。原解析将文明兴衰整个归入社会意识，并断定生态环境从根本上决定文明兴衰，超出了讲话原意和唯物史观原理可以支持的范围。[2013年5月24日讲话节录](https://cpc.people.com.cn/xuexi/n1/2016/1201/c385476-28916113.html) [马克思《〈政治经济学批判〉序言》](https://www.marxists.org/chinese/marx/06.htm)\n\nA项的原论述说明生态保护能够维护生产力和经济社会发展的潜力。仅凭选项所引的一句，尚无法确定哪一方在何种条件下转化为自身的对立面，因此C是否为唯一错误项仍有疑问。[2018年5月18日讲话节录](https://www.ndrc.gov.cn/xwdt/ztzl/NEW_srxxgcjjpjjsx/jjsxyjqk/qkzk2025/202507/zyjh202507/202512/t20251229_1402687.html) [毛泽东《矛盾论》](https://www.htu.edu.cn/xsd/2021/0415/c14329a194041/page.htm)","evidence":"生态兴则文明兴——认识与实践的具体的历史的统一","qids":["政治理论必刷100题#2"]}]},{"title":"实践检验认识与认识指导实践","uses":[{"unit":"Q2","role":"直接考查","use":"《政治理论必刷100题》第7题以建设全国统一大市场为例，所给答案为C（②④）。科学认识能够指导市场建设，落实部署的过程及其成效可以检验相关经济规律性认识。部署须通过实践才能转化为现实成果，规律性认识以经济实践为基础。","evidence":"④“落实党中央部署，加强协调配合”可以检验我们对经济层面的规律性认识","qids":["政治理论必刷100题#7"]}]}],"sources":[{"id":"f2ae00df7a78f44c","label":"认识论 · 实践和认识的辩证关系","topic":"马克思主义哲学","category":"非时政","text":"三、实践和认识的辩证关系\n实践决定认识：实践是认识的来源；实践是认识发展的动力；实践是认识的目的和归宿；\n实践是检验认识真理性的唯一标准。\n认识反作用于实践：科学的认识对实践起促进作用，错误的认识对实践起阻碍作用。\n(粉笔敲黑板：在考试中，\n“实践是认识的唯一途径”经常被设计为干扰选项，考生需高\n度注意， 这个表述本身就是错误的）","source":{"doc":"3ccc56f4000d1642c2d1","first":5,"last":5,"page":5,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{"政治理论必刷100题#2":{"paper":"政治理论必刷100题","n":2,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",1],"asrc":["国省考政治理论必刷100题.pdf",31],"card":"43ce773e203183ac9c97b221","links":[{"id":"k-b2837c1766d1a5a7","role":"解题依据","why":"这一原理要求认识与具体历史条件下的实践相统一，用这一判准可以检验题中的对应关系。"}]},"政治理论必刷100题#7":{"paper":"政治理论必刷100题","n":7,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",2],"asrc":["国省考政治理论必刷100题.pdf",34],"card":"f53a602bfaff93b42ee1fbe7","links":[{"id":"k-b2837c1766d1a5a7","role":"直接考查","why":"经济实践是规律性认识的来源和检验途径，科学认识对实践有指导作用，部署需经实践才能转化为现实成果。"}]}},"terms":{},"references":{"web-2e6ec1ddf52d7118":{"name":"《习近平关于全面建成小康社会论述摘编》节选","url":"https://cpc.people.com.cn/xuexi/n1/2016/1201/c385476-28916113.html"},"web-90788cbf4d8cf58e":{"name":"马克思《〈政治经济学批判〉序言》","url":"https://www.marxists.org/chinese/marx/06.htm"},"web-c3283fe1a8c34858":{"name":"毛泽东《矛盾论》","url":"https://www.htu.edu.cn/xsd/2021/0415/c14329a194041/page.htm"}},"topics":[],"units":{"k-b2837c1766d1a5a7":[["政治理论必刷100题#2"],["政治理论必刷100题#7"]]}};
